"""Export the compiled Arabic Django catalog for live browser components."""

import gettext
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def main():
    with (ROOT / "locale/ar/LC_MESSAGES/django.mo").open("rb") as source:
        catalog = gettext.GNUTranslations(source)._catalog
    messages = {
        key: value for key, value in catalog.items() if isinstance(key, str) and key
    }
    target = ROOT / "static/js/ui_messages.js"
    target.write_text(
        "/* Generated by scripts/build_ui_messages.py; edit django.po, not this file. */\n"
        + "window.TZ_UI_MESSAGES = "
        + json.dumps(messages, ensure_ascii=False, indent=2)
        + ";\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
